            [48] = { str = "Go to #COORD[64,51]# in Westfall. Go to #COORD[61,34]# in Westfall. Go to #COORD[45,50]# in Westfall. Go to #COORD[64,52]# in Westfall. Go to #COORD[62,34]# in Westfall. Go to #COORD[55,41]# in Westfall. Go to #COORD[47,49]# in Westfall. Go to #COORD[44,42]# in Westfall. Go to #COORD[41,21]# in Westfall. Go to #COORD[36,34]# in Westfall. Go to #COORD[34,51]# in Westfall. Go to #COORD[43,60]# in Westfall. Go to #COORD[39,61]# in Westfall. Go to #COORD[35,67]# in Westfall. Kill Dust Devils. Loot them for their Debris Dust Devils can spawn throughout all of Westfall. Their spawn locations are marked on the map Cast Eagle Eye to try and find them", x = 64, y = 51, zone = "Westfall" },
            [49] = { str = "Go to #COORD[40,61]# in Westfall. Look for dust devils, they can spawn all over the zone Don't focus on completing this quest Use eagle eye to find them", x = 40, y = 61, zone = "Westfall" },
            [50] = { str = "#optional ==PAY ATTENTION TO THE UPCOMING SECTION== Press Escape, then go into -> Options -> Controls Check \"Enable Interact Key\" and bind the \"Interact with Target\" option to a key Additionally, it's recommended you enable Enemy Nameplates (Default Key: V) as it allows you to see enemies behind some of the corners inside the tower (Rogue only)" },
            [51] = { str = "Go to #COORD[68,70]# in Westfall. Talk to Agent Kearnen You MUST do this quest your Poisons Turn in #INMathias and the Defias#. Accept #GETKlaven's Tower#. Target #NPCAgent Kearnen#. (Rogue only)", x = 68, y = 70, zone = "Westfall" },
            [52] = { str = "Go to #COORD[71,73]# in Westfall. Go to #COORD[71,76]# in Westfall. Go to #COORD[70,73]# in Westfall. Go to #COORD[71,73]# in Westfall. Go to #COORD[71,76]# in Westfall. Go to #COORD[70,73]# in Westfall. Pick Pocket the Malformed Defias Drone. Loot it for the Defias Tower Key You must be in Stealth to use Pick Pocket The Malformed Defias Drone spawns at the entrance to the tower, then patrols around the outside of it Be careful as he deals a LOT of damage. If your Stealth breaks, quickly use Sprint and run away #VIDEOClick HERE for a video guide#. Kill #NPCMalformed Defias Drone#. (Rogue only)", x = 71, y = 73, zone = "Westfall" },
            [53] = { str = "#optional Equip the Curvewood Dagger for this quest if you don't already have a Dagger equipped (Rogue only)" },
            [54] = { str = "Go to #COORD[70,74]# in Westfall. Travel up to 2nd top floor of the tower. Whilst in Stealth and the Defias Tower Sentries aren't next to you, Jump onto the chair, then onto the lamp, then onto the bookshelf on top of the waypoint location Manually Unstealth, then press your \"Interact with Target\" keybind to open the Duskwood Chest. Loot it for Klaven Mortwake's Journal NOTE: Your Stealth will temporarily stop working after looting Klaven Mortwake's Journal Be prepared to run if you don't kill the Defias Tower Sentries on the 2nd floor. They will most likely aggro you permanently (but not attack you) when you are on top of the bookshelf as it is an evade spot If you have a Dagger in your bags or equipped, you can cast Ambush on the Defias Tower Patrollers and Defias Tower Sentries inside to kill them instantly. Be prepared to run after you kill the first Defias Tower Sentry and remember you can be hit from above. This is slower, but a LOT safer Be careful as the Malformed Defias Drone and Defias Drones can be at the entrance of the tower if you have to run out of it #VIDEOClick HERE for a video guide#. Kill #NPCDefias Tower Patroller#. Kill #NPCDefias Tower Sentry#. (Rogue only)", x = 70, y = 74, zone = "Westfall" },
            [55] = { str = "Go to #COORD[64,51]# in Westfall. Go to #COORD[61,34]# in Westfall. Go to #COORD[45,50]# in Westfall. Go to #COORD[64,52]# in Westfall. Go to #COORD[62,34]# in Westfall. Go to #COORD[55,41]# in Westfall. Go to #COORD[47,49]# in Westfall. Go to #COORD[44,42]# in Westfall. Go to #COORD[41,21]# in Westfall. Go to #COORD[36,34]# in Westfall. Go to #COORD[34,51]# in Westfall. Go to #COORD[43,60]# in Westfall. Go to #COORD[39,61]# in Westfall. Go to #COORD[35,67]# in Westfall. Kill Dust Devils. Loot them for their Debris Dust Devils can spawn throughout all of Westfall. Their spawn locations are marked on the map (Rogue only)", x = 64, y = 51, zone = "Westfall" },
