            [1] = { str = "32-33 Hillsbrad/Arathi I" },
            [2] = { str = "The Shadowy Assassin attack on Southshore is a random event If you ever see a Shadowy Assassin in Southshore, kill them. Loot them for the Assassin's Contract Use the Assassin's Contract to start the quest Skip this step if you don't see the event Accept #GETAssassin's Contract#." },
