            [5] = { str = "Go to #COORD[51,58]# in Hillsbrad Foothills. Talk to Lieutenant Farren Orinelle Accept #GETDown the Coast#. Target #NPCLieutenant Farren Orinelle#.", x = 51, y = 58, zone = "Hillsbrad Foothills" },
