            [7] = { str = "Go to #COORD[49,64]# in Hillsbrad Foothills. Go to #COORD[46,64]# in Hillsbrad Foothills. Go to #COORD[44,67]# in Hillsbrad Foothills. Go to #COORD[41,69]# in Hillsbrad Foothills. Go to #COORD[36,70]# in Hillsbrad Foothills. Go to #COORD[45,67]# in Hillsbrad Foothills. Kill Torn Fin Tidehunters and Torn Fin Oracles Kill #NPCTorn Fin Tidehunter#. Kill #NPCTorn Fin Oracle#.", x = 49, y = 64, zone = "Hillsbrad Foothills" },
            [8] = { str = "Go to #COORD[51,58]# in Hillsbrad Foothills. Talk to Lieutenant Farren Orinelle Turn in #INDown the Coast#. Accept #GETFarren's Proof#. Target #NPCLieutenant Farren Orinelle#.", x = 51, y = 58, zone = "Hillsbrad Foothills" },
            [9] = { str = "Go to #COORD[49,64]# in Hillsbrad Foothills. Go to #COORD[46,64]# in Hillsbrad Foothills. Go to #COORD[44,67]# in Hillsbrad Foothills. Go to #COORD[41,69]# in Hillsbrad Foothills. Go to #COORD[36,70]# in Hillsbrad Foothills. Go to #COORD[45,67]# in Hillsbrad Foothills. Go to #COORD[33,69]# in Hillsbrad Foothills. Go to #COORD[31,73]# in Hillsbrad Foothills. Go to #COORD[29,73]# in Hillsbrad Foothills. Go to #COORD[25,70]# in Hillsbrad Foothills. Go to #COORD[33,69]# in Hillsbrad Foothills. Kill Torn Fin Tidehunters, Torn Fin Oracles, Torn Fin Coastrunners and Torn Fin Muckdwellers. Loot them for their Heads Kill #NPCTorn Fin Muckdweller#. Kill #NPCTorn Fin Coastrunner#. Kill #NPCTorn Fin Tidehunter#. Kill #NPCTorn Fin Oracle#.", x = 49, y = 64, zone = "Hillsbrad Foothills" },
            [10] = { str = "Go to #COORD[51,58]# in Hillsbrad Foothills. Talk to Lieutenant Farren Orinelle Turn in #INFarren's Proof#. Accept #GETFarren's Proof#. Target #NPCLieutenant Farren Orinelle#.", x = 51, y = 58, zone = "Hillsbrad Foothills" },
            [11] = { str = "Go to #COORD[49,59]# in Hillsbrad Foothills. Talk to Marshal Redpath Turn in #INFarren's Proof#. Accept #GETFarren's Proof#. Target #NPCMarshal Redpath#.", x = 49, y = 59, zone = "Hillsbrad Foothills" },
            [12] = { str = "Go to #COORD[51,58]# in Hillsbrad Foothills. Talk to Lieutenant Farren Orinelle Turn in #INFarren's Proof#. Accept #GETStormwind Ho!#. Target #NPCLieutenant Farren Orinelle#.", x = 51, y = 58, zone = "Hillsbrad Foothills" },
            [13] = { str = "Go to #COORD[53,65]# in Hillsbrad Foothills. Go to #COORD[55,63]# in Hillsbrad Foothills. Go to #COORD[58,66]# in Hillsbrad Foothills. Go to #COORD[60,73]# in Hillsbrad Foothills. Go to #COORD[57,67]# in Hillsbrad Foothills. Kill Daggerspine Sirens and Daggerspine Shorehunters You may need to swim out in the water for them Kill #NPCDaggerspine Shorehunter#. Kill #NPCDaggerspine Siren#.", x = 53, y = 65, zone = "Hillsbrad Foothills" },
            [14] = { str = "Go to #COORD[51,58]# in Hillsbrad Foothills. Talk to Lieutenant Farren Orinelle Turn in #INStormwind Ho!#. Accept #GETReassignment#. Target #NPCLieutenant Farren Orinelle#.", x = 51, y = 58, zone = "Hillsbrad Foothills" },
            [15] = { str = "Go to #COORD[48,59]# in Hillsbrad Foothills. Talk to Magistrate Henry Maleb Don't accept the follow up Turn in #INAssassin's Contract#. Target #NPCMagistrate Henry Maleb#.", x = 48, y = 59, zone = "Hillsbrad Foothills" },
            [16] = { str = "Talk to Darla Harris Go to #COORD[49,52]# in Hillsbrad Foothills. Fly to Arathi Highlands Target #NPCDarla Harris#.", x = 49, y = 52, zone = "Hillsbrad Foothills" },
            [17] = { str = "Go to #COORD[46,48]# in Arathi Highlands. Talk to Captain Nials Accept #GETNorthfold Manor#. Target #NPCCaptain Nials#.", x = 46, y = 48, zone = "Arathi Highlands" },
            [18] = { str = "Go to #COORD[47,47]# in Arathi Highlands. Talk to Skuerto Turn in #INMalin's Request#. Target #NPCSkuerto#.", x = 47, y = 47, zone = "Arathi Highlands" },
            [19] = { str = "Go to #COORD[60,54]# in Arathi Highlands. Talk to Quae Turn in #INHints of a New Plague?#. Target #NPCQuae#.", x = 60, y = 54, zone = "Arathi Highlands" },
            [20] = { str = "Go to #COORD[60,54]# in Arathi Highlands. Talk to Quae Turn in #INHints of a New Plague?#. Accept #GETHints of a New Plague?#. Target #NPCQuae#.", x = 60, y = 54, zone = "Arathi Highlands" },
            [21] = { str = "Go to #COORD[26,59]# in Arathi Highlands. Go to #COORD[24,60]# in Arathi Highlands. Go to #COORD[24,58]# in Arathi Highlands. Go to #COORD[27,59]# in Arathi Highlands. Travel to Stromgarde Keep to further train your First Aid Follow the Arrow very closely once you are inside, as there are a lot of Elite mobs in the Keep Talk to Deneb Walker Buy the Expert First Aid - Under Wraps, Manual: Heavy Silk Bandage and Manual: Mageweave Bandage from him Deneb Walker also has limited supply items such as Scrolls and Potions as well which you should buy Target #NPCDeneb Walker#.", x = 26, y = 59, zone = "Arathi Highlands" },
            [22] = { str = "Kill the Forsaken Courier. Loot her for her Sealed Folder The Forsaken Courier patrols the road between Tarren Mill and Go'Shek Farm Cast Eagle Eye to try and find the Forsaken Courier If you can't see them in Arathi, look for them in Hillsbrad after finishing Northfold Manor" },
            [23] = { str = "Go to #COORD[33,33]# in Arathi Highlands. Go to #COORD[30,31]# in Arathi Highlands. Go to #COORD[31,25]# in Arathi Highlands. Go to #COORD[34,29]# in Arathi Highlands. Go to #COORD[31,29]# in Arathi Highlands. Kill Syndicate Mercenaries and Syndicate Highwaymen Be aware Syndicate Highwaymen are in Stealth and can be found around the perimiter of Northfold Manor Cast Perception to help spot Syndicate Highwaymen Kill #NPCSyndicate Highwayman#. Kill #NPCSyndicate Mercenary#.", x = 33, y = 33, zone = "Arathi Highlands" },
            [24] = { str = "Hearth to Southshore Buy food/water if needed (Hunter only)" },
            [25] = { str = "Talk to Wesley Go to #COORD[50,59]# in Hillsbrad Foothills. Stable your pet. You will tame a Plains Creeper shortly Target #NPCWesley#. (Hunter only)", x = 50, y = 59, zone = "Hillsbrad Foothills" },
            [26] = { str = "Talk to Darla Harris Go to #COORD[49,52]# in Hillsbrad Foothills. Fly to Arathi Highlands Target #NPCDarla Harris#. (Hunter only)", x = 49, y = 52, zone = "Hillsbrad Foothills" },
            [27] = { str = "Go to #COORD[46,48]# in Arathi Highlands. Talk to Captain Nials Turn in #INNorthfold Manor#. Target #NPCCaptain Nials#.", x = 46, y = 48, zone = "Arathi Highlands" },
            [28] = { str = "Go to #COORD[42,48]# in Arathi Highlands. Go to #COORD[42,59]# in Arathi Highlands. Go to #COORD[49,50]# in Arathi Highlands. Go to #COORD[42,48]# in Arathi Highlands. Go to #COORD[42,59]# in Arathi Highlands. Go to #COORD[49,50]# in Arathi Highlands. Go to #COORD[48,59]# in Arathi Highlands. Cast Eagle Eye to try and find a Plains Creeper. Some of their locations are marked on your map Cast Tame Beast on a Plains Creeper to tame it Attack mobs with it to learn Bite (Rank 5) #VIDEOClick here for more info about pet training#. (Hunter only)", x = 42, y = 48, zone = "Arathi Highlands" },
            [29] = { str = "Go to #COORD[60,54]# in Arathi Highlands. Talk to Quae Don't go out of your way to find the Forsaken Courier. You can skip this step and finish it later Turn in #INHints of a New Plague?#. Target #NPCQuae#.", x = 60, y = 54, zone = "Arathi Highlands" },
            [30] = { str = "Talk to Darla Harris or Cedrik Prose Talk to Cedrik Prose Go to #COORD[49,52]# in Hillsbrad Foothills. Go to #COORD[46,46]# in Arathi Highlands. Fly to Wetlands Target #NPCDarla Harris#. Target #NPCCedrik Prose#.", x = 49, y = 52, zone = "Hillsbrad Foothills" },
            [31] = { str = "Talk to Bethaine Flinthammer Go to #COORD[11,60]# in Wetlands. Withdraw your pet from the Stable Target #NPCBethaine Flinthammer#. (Hunter only)", x = 11, y = 60, zone = "Wetlands" },
            [32] = { str = "Go to #COORD[11,60]# in Wetlands. Talk to Vincent Hyal Turn in #INJames Hyal#. Accept #GETJames Hyal#. Target #NPCVincent Hyal#.", x = 11, y = 60, zone = "Wetlands" },
            [33] = { str = "Go to #COORD[11,61]# in Wetlands. Talk to Mikhail Accepting this quest will make Tapoke \"Slim\" Jahn by the Inn entrance Stealth and run away outside Turn in #INThe Missing Diplomat#. Accept #GETThe Missing Diplomat#. Target #NPCMikhail#. Kill #NPCTapoke \"Slim\" Jahn#.", x = 11, y = 61, zone = "Wetlands" },
            [34] = { str = "Go to #COORD[11,60]# in Wetlands. Quickly run outside! Defeat Tapoke \"Slim\" Jahn. Slim's Friend will run away once Tapoke \"Slim\" Jahn submits Use any Crowd Control (CC) on Slim's Friend if needed Kill #NPCTapoke \"Slim\" Jahn#.", x = 11, y = 60, zone = "Wetlands" },
            [35] = { str = "Go to #COORD[11,61]# in Wetlands. Talk to Mikhail Turn in #INThe Missing Diplomat#. Target #NPCMikhail#.", x = 11, y = 61, zone = "Wetlands" },
            [36] = { str = "Go to #COORD[11,60]# in Wetlands. Talk to Tapoke \"Slim\" Jahn Accept #GETThe Missing Diplomat#. Target #NPCTapoke \"Slim\" Jahn#.", x = 11, y = 60, zone = "Wetlands" },
            [37] = { str = "Go to #COORD[11,61]# in Wetlands. Talk to Mikhail Turn in #INThe Missing Diplomat#. Accept #GETThe Missing Diplomat#. Target #NPCMikhail#.", x = 11, y = 61, zone = "Wetlands" },
